-- Catálogo de partidas de HU-07 con el Arancel de Aduanas 2022 (D.S. N.° 404-2021-EF).
-- Fuente: https://www.sunat.gob.pe/orientacionaduanera/aranceles/2022/arancel-ad-2022.pdf
-- 8017 subpartidas nacionales de 10 dígitos con su tasa Ad Valorem (A/V). La descripción
-- incluye los niveles superiores (p. ej. «Balones y pelotas … › Inflables») para que los
-- textos «Los demás» tengan sentido; la búsqueda incluye además el texto de la partida.
-- Sigue siendo un catálogo referencial interno: no se consulta en línea a SUNAT.

ALTER TABLE partida_referencial
    ALTER COLUMN descripcion TYPE VARCHAR(1000),
    ALTER COLUMN busqueda TYPE VARCHAR(2000);

-- Las partidas de ejemplo del V007 que no existen en el arancel oficial salen del buscador;
-- se conservan las filas por si algún ítem ya las usa.
UPDATE partida_referencial SET activo = FALSE;

ON CONFLICT (codigo) DO UPDATE SET descripcion = EXCLUDED.descripcion,
    tasa_ad_valorem = EXCLUDED.tasa_ad_valorem, busqueda = EXCLUDED.busqueda, activo = TRUE;

ON CONFLICT (codigo) DO UPDATE SET descripcion = EXCLUDED.descripcion,
    tasa_ad_valorem = EXCLUDED.tasa_ad_valorem, busqueda = EXCLUDED.busqueda, activo = TRUE;

ON CONFLICT (codigo) DO UPDATE SET descripcion = EXCLUDED.descripcion,
    tasa_ad_valorem = EXCLUDED.tasa_ad_valorem, busqueda = EXCLUDED.busqueda, activo = TRUE;

ON CONFLICT (codigo) DO UPDATE SET descripcion = EXCLUDED.descripcion,
    tasa_ad_valorem = EXCLUDED.tasa_ad_valorem, busqueda = EXCLUDED.busqueda, activo = TRUE;

ON CONFLICT (codigo) DO UPDATE SET descripcion = EXCLUDED.descripcion,
    tasa_ad_valorem = EXCLUDED.tasa_ad_valorem, busqueda = EXCLUDED.busqueda, activo = TRUE;

ON CONFLICT (codigo) DO UPDATE SET descripcion = EXCLUDED.descripcion,
